import{_ as t,o as _,c as a,a4 as r}from"./chunks/framework.hWlsC8BY.js";const i=JSON.parse('{"title":"（活力中国调研行）从“指尖种田”到农机出海 河南智慧农业助农省力增收","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"（活力中国调研行）从“指尖种田”到农机出海 河南智慧农业助农省力增收","date":"2026-09-19T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202609/t20260918_6487786.htm","summary":"中新社河南新乡9月10日电 　 (记者 官逸伦 范晓恒)只需打开手机应用程序,苏亚宁就能查看最新的无人机巡田报告,了解农田的病虫害情况。这位来自河南省新乡市获嘉县位庄乡的种粮大户日前接受中新社记者采访时表示,“这能给我们提供预警,提醒我们要喷洒哪种药物来防治病虫害。”\\n除了购买无人机巡田服务,苏亚宁还在农田中铺设了水肥一体化设施,通过对水肥的精准调控,玉米亩产提升超100斤。\\n...\\n","contentHash":"1853752980fff03a4c1a302fd5e1e311","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-09-19-活力中国调研行-从-指尖种田-到农机出海-河南智慧农业助农省力增收.md","filePath":"news/2026-09-19-活力中国调研行-从-指尖种田-到农机出海-河南智慧农业助农省力增收.md"}'),n={name:"news/2026-09-19-活力中国调研行-从-指尖种田-到农机出海-河南智慧农业助农省力增收.md"};function s(o,e,p,l,d,c){return _(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="活力中国调研行-从-指尖种田-到农机出海-河南智慧农业助农省力增收" tabindex="-1">（活力中国调研行）从“指尖种田”到农机出海 河南智慧农业助农省力增收 <a class="header-anchor" href="#活力中国调研行-从-指尖种田-到农机出海-河南智慧农业助农省力增收" aria-label="Permalink to &quot;（活力中国调研行）从“指尖种田”到农机出海 河南智慧农业助农省力增收&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202609/t20260918_6487786.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-09-19 摘要: 中新社河南新乡9月10日电 　 (记者 官逸伦 范晓恒)只需打开手机应用程序,苏亚宁就能查看最新的无人机巡田报告,了解农田的病虫害情况。这位来自河南省新乡市获嘉县位庄乡的种粮大户日前接受中新社记者采访时表示,“这能给我们提供预警,提醒我们要喷洒哪种药物来防治病虫害。” 除了购买无人机巡田服务,苏亚宁还在农田中铺设了水肥一体化设施,通过对水肥的精准调控,玉米亩产提升超100斤。 ...</p></blockquote><p>除了购买无人机巡田服务,苏亚宁还在农田中铺设了水肥一体化设施,通过对水肥的精准调控,玉米亩产提升超100斤。</p><p>苏亚宁表示,科技的应用让农民有了更多收益,也让种地变得更省力,将吸引更多年轻人从事农业生产。他说,随着农业科技发展,农作物将具有更大品牌价值。</p><p>获嘉县艳阳天农业服务专业合作社理事长徐方子也是水肥一体化技术的受益者。如今,他在1900亩农田中铺设滴灌带,只需通过5名管理人员规范操作,就能基本实现按需施肥和精准浇灌。</p><p>徐方子认为,实现省工增产的水肥一体化技术将是农作物规模化种植的关键保障。借助物联网技术,徐方子尝试通过微信小程序管理500亩试验田:只要点点手机,就能选地块、开阀门,足不出户完成浇地、施肥。</p><p>据徐方子估算,在维持同等产量的情况下,使用水肥一体化技术可减少化肥使用量约20%,减少灌溉用水量约30%。</p><p>新乡市花溪科技股份有限公司董事长孟家毅表示,随着科技在农业实践中得到广泛应用,如何利用科技手段推动农业绿色发展将是未来关注重点之一。</p><p>该公司主要研发、制造各类打捆机,产品广泛应用于各类作物秸秆收集作业,支持秸秆综合利用,助力农民增收与生态改良。</p><p>目前,该公司生产的打捆机已出口泰国、澳大利亚、埃及、巴基斯坦等国,并结合当地农民使用习惯进行相应调整。孟家毅称,产品的质量和性价比是国外客户在购买打捆机时考虑的主要因素,中国的农机产品已经能够和国外农机产品站在同一舞台上较量。(完)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202609/t20260918_6487786.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',11)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
